--
-- Table structure for table `transaksi`
--

CREATE TABLE `transaksi` (
  `id_transaksi` int(11) NOT NULL,
  `id_transaksi_pelunasan` varchar(25) NOT NULL,
  `no_transaksi` varchar(25) NOT NULL,
  `kategori_transaksi` varchar(25) NOT NULL,
  `id_metode_pembayaran` varchar(25) NOT NULL,
  `pembayaran` varchar(50) NOT NULL,
  `id_user` varchar(25) NOT NULL,
  `input_by` varchar(25) NOT NULL,
  `id_pengunjung` varchar(25) NOT NULL,
  `nama_pengunjung` text NOT NULL,
  `nohp_pengunjung` text NOT NULL,
  `kategori_pengunjung` varchar(55) NOT NULL,
  `fitur` varchar(50) NOT NULL DEFAULT 'Fasilitas Olahraga',
  `fasilitas` text NOT NULL,
  `paket` varchar(100) NOT NULL,
  `id_fasilitas` varchar(25) NOT NULL,
  `id_akun_pendapatan` varchar(20) NOT NULL,
  `id_outlet` varchar(25) NOT NULL,
  `kelompok_fasilitas` varchar(25) NOT NULL,
  `id_kategori_kelas` varchar(5) NOT NULL,
  `keterangan` text NOT NULL,
  `tgl_transaksi` text NOT NULL,
  `jam_transaksi` text NOT NULL,
  `order_ke` int(11) NOT NULL,
  `order_ke_fasilitas` int(11) NOT NULL,
  `kategori_potongan` text NOT NULL,
  `jenis_potongan` text NOT NULL,
  `id_diskon` varchar(5) NOT NULL,
  `nama_diskon` varchar(50) NOT NULL,
  `besar_diskon` text NOT NULL,
  `rp_nilai_diskon` int(11) NOT NULL,
  `total` text NOT NULL,
  `tagihan` int(11) NOT NULL,
  `status` varchar(25) NOT NULL,
  `dp` varchar(25) NOT NULL,
  `sisa_pembayaran` varchar(25) NOT NULL,
  `dibayar` varchar(50) NOT NULL,
  `kembalian` varchar(25) NOT NULL,
  `updated_by` varchar(25) NOT NULL,
  `updated_at` varchar(25) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

